-- MailPilot AI: private attachment storage.
-- Objects are stored as <user_id>/<attachment_id>/<sanitized filename>.
-- Only the backend (service role) uploads; users may read their own objects,
-- and the UI receives short-lived signed URLs generated by the backend.

insert into storage.buckets (id, name, public, file_size_limit)
values ('attachments', 'attachments', false, 52428800)
on conflict (id) do update set public = false, file_size_limit = excluded.file_size_limit;

create policy attachments_read_own on storage.objects
  for select to authenticated
  using (bucket_id = 'attachments' and (storage.foldername(name))[1] = (select auth.uid())::text);
